/* Types */
export type AccountKind = "microsoft" | "offline";

/**  After a removal: which account is active now. */
export type AccountRemoval = {
	/**  Another account when the removed one was active; `None` when none is left. */
	activeId: string | null,
};

/**  Account as the UI shows it (no secrets ever cross this boundary). */
export type AccountView = {
	id: string,
	kind: AccountKind,
	username: string,
	/**  Minecraft profile UUID without dashes. */
	uuid: string,
	active: boolean,
	skinUrl: string | null,
	/**  The player's head (8×8 PNG data URL) once it is cached; see `accounts_ensure_heads`. */
	headUrl: string | null,
	/**  When the account was added (RFC 3339). */
	addedAt: string,
	/**  Last time the game was started with it (RFC 3339). */
	lastUsedAt: string | null,
	/**  Microsoft refused the saved session: a new sign-in is needed. */
	needsRelogin: boolean,
	/**  Pinned: listed first, in the player's order. */
	pinned: boolean,
	/**  Bundled picture shown instead of the head (`preset:<slug>`, offline accounts). */
	avatar: string | null,
};

/**  What this launcher tells friends (the player's own card). */
export type ActivityView = { state: "launcher" } | { state: "playing"; host: string | null } | { state: "singleplayer" };

/**  An add-on file and what is known about it. */
export type AddonEntry = {
	kind: ImportKind,
	/**  File name in its folder (with `.disabled` when disabled). */
	fileName: string,
	enabled: boolean,
	size: number,
	/**  Lowercase hex SHA-1. */
	sha1: string,
	source: AddonSource | null,
	/**  Set by [`Addons::check_updates`] when a newer compatible version exists. */
	update: AddonUpdate | null,
};

export type AddonInstallReport = {
	/**  New files, the requested versions first, then dependencies. */
	installed: AddonInstalled[],
	/**  Requested versions that were already installed. */
	alreadyInstalled: AddonInstalled[],
	/**  Older files of the same projects that were removed. */
	replaced: string[],
	/**  Required dependencies that could not be installed. */
	unresolved: ModrinthUnresolvedDependency[],
	/**  Installed projects that a new version declares incompatible. */
	conflicts: ModrinthDependencyConflict[],
};

/**  A file [`Addons::install`] put in place (or found already there). */
export type AddonInstalled = {
	kind: ImportKind,
	projectId: string,
	versionId: string,
	versionNumber: string,
	title: string | null,
	fileName: string,
	/**  Installed because another project requires it. */
	dependency: boolean,
};

/**  The Modrinth project and version a file belongs to. */
export type AddonSource = {
	projectId: string,
	versionId: string,
	versionNumber?: string | null,
	title?: string | null,
	iconUrl?: string | null,
};

/**  A newer compatible version of an installed add-on. */
export type AddonUpdate = {
	versionId: string,
	versionNumber: string,
	versionType: ModrinthVersionType,
	datePublished: string,
};

/**  Payload of [`ADOPTED_GAME_EXITED`]. */
export type AdoptedGameExit = {
	game: number,
	instanceId: string,
};

/**
 *  A game an earlier start of the launcher left running, followed again by this start
 *  ([`adopt_detached`]): the page shows it as "Oyunda" from its first paint.
 */
export type AdoptedGameView = {
	/**  The launcher's number for it (as `LaunchEventView::Started::game`). */
	game: number,
	instanceId: string,
	/**  When its window showed (Unix milliseconds); the session time counts from there. */
	sinceMs: number,
	/**
	 *  The account it plays with; none when an older launcher left it running (it then counts as
	 *  every account's).
	 */
	account: GameAccount | null,
};

export type AfkAccountView = {
	id: string,
	nickname: string,
	server: string,
	autoStart: boolean,
	/**
	 *  The game version the client connects with: `auto` or a listed value (the recommended one
	 *  when the account follows it or stored a version the list does not know).
	 */
	mcVersion: string,
	/**  `mc_version` is the recommended version (no version chip then). */
	mcVersionRecommended: boolean,
	state: SessionState,
	stats: SessionStats,
	running: boolean,
	/**  The running client was launched with older settings; they apply after a reconnect. */
	settingsChanged: boolean,
	/**  Show the date next to the time in the live console (chat log settings). */
	showDate: boolean,
	/**
	 *  The account waits for the AFK client (the step, with the download's progress), or its
	 *  last connect could not get it (`failed`, with the problem to word).
	 */
	client: ClientStep | null,
};

/**
 *  The client's answer to a press of the card: done, or why not (`stale`: another dialog now;
 *  anything else: it did not work).
 */
export type AfkDialogOutcome = {
	ok: boolean,
	why: string | null,
};

/**
 *  The server's dialog of a desktop account as its console card shows it (DIALOG-CARD on this
 *  computer): its JSON as pl-afk checked it (the view checks it again: `safeDialog`).
 */
export type AfkDialogView = {
	/**  The client's revision of it: a press names it. */
	rev: number,
	dialog: string,
	/**  When it opened (RFC 3339). */
	at: string,
};

export type AfkEvent = {
	accountId: string,
	kind: AfkEventKind,
};

export type AfkEventKind = { type: "state"; data: SessionState } | 
/**  A console line (already masked). */
{ type: "line"; data: ConsoleLine } | { type: "stats"; data: SessionStats } | 
/**  The account auto-responded to `user`; `sound` mirrors the account's notification setting. */
{ type: "autoRespond"; data: {
	user: string | null,
	sound: boolean,
} } | 
/**  Bulk connect: seconds until this account connects; 0 clears the countdown. */
{ type: "countdown"; data: {
	secs: number,
} } | 
/**
 *  The account waits for the AFK client (download progress included), or its connect could
 *  not get it; `None` once that is over (see [`crate::client`]).
 */
{ type: "client"; data: ClientStep | null } | 
/**
 *  The server's dialog of the account opened, changed or closed (the console's card reads it
 *  again).
 */
{ type: "dialog" };

/**  An item's name in Turkish and English (from the AFK+ catalog). */
export type AfkItemName = {
	tr: string,
	en: string,
};

/**
 *  One notice. `event`: `stopped`, `renewal`, `expired`, `found`, `approval`, `approval_closed`,
 *  `deal_done`, `deal_failed`, `quota`, `summary`, `paused`, `incident`, `message`, `weekly`, or the
 *  service's own `night` (kept as text, so a newer event still arrives). `kind`: `afk_alert`,
 *  `afk_deal`, `afk_info`; `priority`: `high` or `normal`.
 */
export type AfkNotice = AfkNotice_Serialize | AfkNotice_Deserialize;

/**
 *  One notice. `event`: `stopped`, `renewal`, `expired`, `found`, `approval`, `approval_closed`,
 *  `deal_done`, `deal_failed`, `quota`, `summary`, `paused`, `incident`, `message`, `weekly`, or the
 *  service's own `night` (kept as text, so a newer event still arrives). `kind`: `afk_alert`,
 *  `afk_deal`, `afk_info`; `priority`: `high` or `normal`.
 */
export type AfkNotice_Deserialize = {
	/**  A ULID, the same on every retry (`night:<until>` for the night's digest). */
	id?: string,
	event?: string,
	kind?: string,
	priority?: string,
	/**  Unix seconds. */
	at?: number,
	/**  A newer notice with the same tag replaces this one (`approval:<id>`). */
	tag?: string | null,
	/**  The player's quiet hours: shown in the launcher only, without a system notification. */
	quiet?: boolean,
	/**
	 *  Account ids, item ids, amounts, times, reason codes and the bot account's own name
	 *  (`name`); never a counterpart's name or a message's text. Numbers that come as numbers read
	 *  as their text.
	 */
	data?: { [key in string]: string },
	/**
	 *  The item's name in both languages, when this launcher knows the mode's catalog (filled in
	 *  by the launcher; the service never sends it).
	 */
	itemName?: AfkItemName | null,
};

/**
 *  One notice. `event`: `stopped`, `renewal`, `expired`, `found`, `approval`, `approval_closed`,
 *  `deal_done`, `deal_failed`, `quota`, `summary`, `paused`, `incident`, `message`, `weekly`, or the
 *  service's own `night` (kept as text, so a newer event still arrives). `kind`: `afk_alert`,
 *  `afk_deal`, `afk_info`; `priority`: `high` or `normal`.
 */
export type AfkNotice_Serialize = {
	/**  A ULID, the same on every retry (`night:<until>` for the night's digest). */
	id: string,
	event: string,
	kind: string,
	priority: string,
	/**  Unix seconds. */
	at: number,
	/**  A newer notice with the same tag replaces this one (`approval:<id>`). */
	tag: string | null,
	/**  The player's quiet hours: shown in the launcher only, without a system notification. */
	quiet: boolean,
	/**
	 *  Account ids, item ids, amounts, times, reason codes and the bot account's own name
	 *  (`name`); never a counterpart's name or a message's text. Numbers that come as numbers read
	 *  as their text.
	 */
	data: { [key in string]: string },
	/**
	 *  The item's name in both languages, when this launcher knows the mode's catalog (filled in
	 *  by the launcher; the service never sends it).
	 */
	itemName: AfkItemName | null,
};

/**  Account-independent AFK preferences (`settings.json`). */
export type AfkSettings = {
	/**
	 *  Show login-script lines in the console. Lines with passwords stay hidden (and are masked
	 *  at the source) either way.
	 */
	showScriptCommands?: boolean,
};

/**  Outcome of saving the settings sheet. Incomplete settings are an expected outcome, not an error. */
export type AfkSettingsSaveResult = 
/**  Saved. `settings` is the stored page (normalized; passwords still left out). */
{ status: "saved"; settings: SettingsPage; 
/**  The running client keeps its old settings until it reconnects. */
reconnectNeeded: boolean } | 
/**  Nothing was saved. */
{ status: "invalid"; issues: ValidationIssue[] };

/**  Everything the settings sheet of one account needs. */
export type AfkSettingsView = {
	/**
	 *  Login commands that carry a password are listed by name only; the password stays in the
	 *  OS keychain.
	 */
	settings: SettingsPage,
	/**
	 *  Game versions the AFK client can join, in picker order: `auto` first, then the versions
	 *  newest first; one is flagged recommended (the content index's list, else the built-in one).
	 */
	versions: VersionOption[],
	/**
	 *  The account stored a version the list does not know: the page shows (and the client uses)
	 *  the recommended one instead.
	 */
	unknownVersion: string | null,
	/**
	 *  False when the OS keychain is unavailable: login commands then only last until the launcher
	 *  closes.
	 */
	keychainAvailable: boolean,
	/**
	 *  Command names whose arguments are passwords (lowercase): the sheet masks such lines while
	 *  they are typed, and saved ones come back as stored lines.
	 */
	sensitiveCommands: string[],
};

export type AlertsOptions = {
	enabled?: boolean,
	beepEnabled?: boolean,
	triggerByWords?: boolean,
	logToFile?: boolean,
	matches?: string[],
	excludes?: string[],
};

/**  Periodic movement/command that keeps the server from flagging the account as AFK. */
export type AntiAfkOptions = {
	enabled?: boolean,
	/**  Seconds; MCC picks a random delay in `[delay_min, delay_max]`. */
	delayMin?: number | null,
	delayMax?: number | null,
	/**  Sent every round; empty means "move only". */
	command?: string,
	useSneak?: boolean,
	/**  Random walking; forces MCC terrain handling on (see the config writer). */
	useTerrainHandling?: boolean,
	walkRange?: number,
	walkRetries?: number,
};

export type AppInfo = {
	version: string,
	os: string,
	arch: string,
	debug: boolean,
	/**
	 *  False when the OS keychain is unavailable (Linux without Secret Service): account
	 *  sign-ins then last only for this session.
	 */
	secureStorage: boolean,
	dataDir: string,
	/**  Started at login: the window stays in the tray until the user opens it. */
	startMinimized: boolean,
	/**  Installed RAM, for memory sliders. */
	systemMemoryMb: number,
};

/**  The active skin of an account. */
export type AppearanceSkin = {
	/**  Texture on textures.minecraft.net (HTTPS). */
	url: string,
	variant: SkinVariant,
	/**  One of Mojang's default skins (Steve, Alex and the others) rather than an upload. */
	isDefault: boolean,
};

/**  What the appearance panel shows for a Microsoft account. */
export type AppearanceView = {
	accountId: string,
	username: string,
	skin: AppearanceSkin | null,
	/**  Capes the profile owns; at most one is `active`. */
	capes: Cape[],
	/**  Minecraft Services could not be reached: this is the saved copy and may be out of date. */
	stale: boolean,
};

/**  Sign-in state of this launcher. */
export type AuthPhase = "signedOut" | 
/**  The browser is open on Discord; waiting for the `projects://auth/done` link. */
"signingIn" | 
/**  A saved session is being checked at start. */
"restoring" | "signedIn";

/**  Eat when the food bar drops below the threshold; forces MCC inventory handling on. */
export type AutoEatOptions = {
	enabled?: boolean,
	/**  Food bar value, 0-20. */
	threshold?: number,
};

/**
 *  Reconnect after a disconnect. With the launcher bridge MCC exits on every failure, so these
 *  settings drive the launcher-side restart loop (delays, retry limit and kick-message filter; see
 *  [`crate::RestartSchedule`]).
 */
export type AutoRelogOptions = {
	enabled?: boolean,
	/**  Seconds before the first restart; later restarts wait longer, up to `delay_max`. */
	delayMin?: number | null,
	delayMax?: number | null,
	/**  -1 means unlimited. */
	retries?: number,
	/**  True: reconnect whatever the kick message says. */
	ignoreKickMessage?: boolean,
	kickMessages?: string[],
};

/**
 *  One row of the auto-respond grid. Replies are what the user types (`selam`, `/home`); the
 *  `send ` prefix MCC needs is added on save (see [`display_to_action`]).
 */
export type AutoRespondRule = {
	pattern?: string,
	reply?: string,
	privateReply?: string,
	otherReply?: string,
	ownersOnly?: boolean,
	cooldownSeconds?: number,
	isRegex?: boolean,
};

export type AutoRespondSettings = {
	enabled?: boolean,
	soundEnabled?: boolean,
	matchColors?: boolean,
	rules?: AutoRespondRule[],
};

/**  Progress of a world backup. */
export type BackupProgress = {
	filesDone: number,
	filesTotal: number,
	bytesDone: number,
	bytesTotal: number,
};

/**
 *  Why the launcher made a backup by itself. It travels inside the archive (its zip comment), so
 *  it stays with the file when the folder is copied, and the game and other tools ignore it.
 */
export type BackupReason = 
/**
 *  Before the world first opened to friends from the launcher (HOST1, "Arkadaşlarına
 *  açılmadan önce").
 */
"beforeSharing";

/**  Why a join request from a tag's card did not go (TEAM6). */
export type BadgeRefusal = 
/**
 *  "Bu ekip şu an etiketten istek almıyor.": the card was stale (the tag came off, the crew
 *  was hidden or stopped taking them, the wearer is no longer a friend, the crew is gone).
 */
"closed" | 
/**  "Bu ekip bugün daha fazla istek almıyor.": the crew's 10 from its tag today. */
"today" | 
/**  "Bu ekibin bekleyen istekleri dolu.": 20 wait at the crew. */
"waitingFull" | 
/**  "Bu ekip dolu." */
"full" | 
/**  "Bu ekipte engellediğin biri var.": the player's own block. */
"blocked" | 
/**  The player has 3 join requests waiting (TEAM5's words). */
"ownWaiting" | 
/**  The player is in as many crews as they may be (TEAM4's words). */
"ownCrews" | 
/**  The player's 10 join requests today (TEAM5's words). */
"ownDaily" | 
/**  The player is in that crew already. */
"member";

/**
 *  What "Katılma isteği gönder" on a tag's card led to (TEAM6). A refusal is an answer, not an
 *  error: one quiet line on the card says why (never a toast), and the button stays away for that
 *  crew on this computer until `until`, the end of the Turkey day; nothing is tried again.
 */
export type BadgeRequestResult = 
/**
 *  The request waits for the crew's leaders ("İsteğin bekliyor · Geri çek"; it is in
 *  `teamRequests`), also when one waited already.
 */
{ status: "sent" } | { status: "refused"; reason: BadgeRefusal; 
/**  Unix seconds: the end of today in Turkey (UTC+3). */
until: number };

