	/**  The own mods with a version for `to` (one entry per mod). */
	compatible: MigrationMoveView[],
	/**  Own mods the target set already has. */
	alreadyThere: number,
	/**  Modrinth could not be reached: the full search ([`mods_migration_plan`]) stays on demand. */
	offline: boolean,
