/**  Why an auto-respond pattern can not be used. */
export type PatternProblem = 
/**  Longer than [`MAX_PATTERN_CHARS`] characters. */
"tooLong" | 
/**  Not a regular expression the client reads (or a control character in the text). */
"invalid" | 
/**
 *  A repetition inside a repetition, a repetition that can split a line more than one way
 *  (rounds that may be empty or start like each other), more than three loops that can hand
 *  characters to what follows them, or a count above 1000: the client could take forever on
 *  some chat lines.
 */
"tooComplex";

/**
 *  `POST /accounts/:id/rules/pattern` → `suggestion`: a trigger made from the player's words. Every
 *  field is the contract's (no defaults: one shape for both directions in the bindings).
 */
export type PatternSuggestion = {
	/**
	 *  False: the message contains `match` (any letter case); true: a pattern that starts with
	 *  `(?i)`.
	 */
	regex: boolean,
	/**  The rule's trigger, ready to save. */
	match: string,
	/**  One sentence a 13-year-old understands: when the rule answers. */
	summary: string,
	/**  One to three messages it answers. */
	matches: string[],
	/**  One or two similar messages it leaves alone. */
	misses: string[],
	/**
	 *  `plain` (the words themselves, no model), `ai` or `cache`: "Tekrar dene" only after the
	 *  model.
	 */
	source: string,
};

/**
 *  A mark the player changed on a friend from the game's person menu (OVL-UX2): the launcher's
 *  page keeps these (its friend list's star and "Çevrimiçi olunca bildir"), so it hears them as
 *  the `overlay-people` event and keeps them as its own buttons would.
 */
